package ledger

import (
	"errors"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// Column widths for the fixed-width ledger layout.
const (
	dateWidth   = 10
	descWidth   = 25
	amountWidth = 13
)

// FormatLedger renders a formatted ledger for the given currency and locale.
//
// Refactor log (see .docs/instructions.md):
//   - Replaced the hand-rolled selection sort with sort.Slice and an explicit
//     (date, description, change) comparator.
//   - Replaced the goroutine-per-entry channel pipeline with a plain sequential
//     loop; the concurrency added no value and obscured the error handling.
//   - Broke formatting into small helpers: header, row, formatDate,
//     formatDescription, formatAmount, formatNumber, currencySymbol.
//   - Centralised input validation (currency, locale, date) up front.
//   - Assembled the output with a strings.Builder instead of string
//     concatenation.
//   - The input slice is copied before sorting so it is never mutated.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	symbol, err := currencySymbol(currency)
	if err != nil {
		return "", err
	}
	if err := validateLocale(locale); err != nil {
		return "", err
	}
	for _, e := range entries {
		if err := validateDate(e.Date); err != nil {
			return "", err
		}
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(header(locale))
	for _, e := range sorted {
		b.WriteString(row(locale, symbol, e))
	}
	return b.String(), nil
}

// header returns the column-heading line for the given locale.
func header(locale string) string {
	var date, desc, change string
	switch locale {
	case "nl-NL":
		date, desc, change = "Datum", "Omschrijving", "Verandering"
	default: // en-US
		date, desc, change = "Date", "Description", "Change"
	}
	return padRight(date, dateWidth) + " | " + padRight(desc, descWidth) + " | " + change + "\n"
}

// row renders a single ledger entry as one line.
func row(locale, symbol string, e Entry) string {
	return formatDate(locale, e.Date) +
		" | " +
		formatDescription(e.Description) +
		" | " +
		padRightRune(formatAmount(locale, symbol, e.Change), amountWidth) +
		"\n"
}

// formatDate rewrites an ISO "YYYY-MM-DD" date into the locale's format.
func formatDate(locale, date string) string {
	year, month, day := date[0:4], date[5:7], date[8:10]
	switch locale {
	case "nl-NL":
		return day + "-" + month + "-" + year
	default: // en-US
		return month + "/" + day + "/" + year
	}
}

// formatDescription pads the description, truncating overlong values.
func formatDescription(desc string) string {
	if len(desc) > descWidth {
		return desc[:descWidth-3] + "..."
	}
	return padRight(desc, descWidth)
}

// formatAmount renders a change in cents using the locale's conventions.
func formatAmount(locale, symbol string, change int) string {
	negative := change < 0
	if negative {
		change = -change
	}
	thousandsSep, decimalSep := ",", "."
	if locale == "nl-NL" {
		thousandsSep, decimalSep = ".", ","
	}
	number := formatNumber(change, thousandsSep, decimalSep)

	switch locale {
	case "nl-NL":
		// e.g. "$ 1.234,56 " (positive) or "$ 123,45-" (negative)
		marker := " "
		if negative {
			marker = "-"
		}
		return symbol + " " + number + marker
	default: // en-US
		if negative {
			return "(" + symbol + number + ")"
		}
		return symbol + number + " "
	}
}

// formatNumber formats a non-negative cent amount into an integer part grouped
// in thousands and a two-digit fractional part.
func formatNumber(cents int, thousandsSep, decimalSep string) string {
	s := strconv.Itoa(cents)
	switch len(s) {
	case 1:
		s = "00" + s
	case 2:
		s = "0" + s
	}
	intPart, fracPart := s[:len(s)-2], s[len(s)-2:]

	var groups []string
	for len(intPart) > 0 {
		start := len(intPart) - 3
		if start < 0 {
			start = 0
		}
		groups = append(groups, intPart[start:])
		intPart = intPart[:start]
	}
	for i, j := 0, len(groups)-1; i < j; i, j = i+1, j-1 {
		groups[i], groups[j] = groups[j], groups[i]
	}
	return strings.Join(groups, thousandsSep) + decimalSep + fracPart
}

// currencySymbol maps a currency code to its symbol.
func currencySymbol(currency string) (string, error) {
	switch currency {
	case "USD":
		return "$", nil
	case "EUR":
		return "€", nil
	}
	return "", errors.New("invalid currency")
}

// validateLocale rejects any locale other than the two supported ones.
func validateLocale(locale string) error {
	switch locale {
	case "en-US", "nl-NL":
		return nil
	}
	return errors.New("invalid locale")
}

// validateDate checks that a date is a well-formed "YYYY-MM-DD" value.
func validateDate(date string) error {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return errors.New("invalid date")
	}
	month, err := strconv.Atoi(date[5:7])
	if err != nil || month < 1 || month > 12 {
		return errors.New("invalid date")
	}
	day, err := strconv.Atoi(date[8:10])
	if err != nil || day < 1 || day > 31 {
		return errors.New("invalid date")
	}
	return nil
}

// padRight pads s with spaces on the right to reach width bytes.
func padRight(s string, width int) string {
	return s + strings.Repeat(" ", width-len(s))
}

// padRightRune pads s with spaces on the right so the result is width runes
// wide. Used for the amount column, which may contain multi-byte symbols.
func padRightRune(s string, width int) string {
	return strings.Repeat(" ", width-utf8.RuneCountInString(s)) + s
}
